import{z as o,x as L,o as l,c as i,q as E,j as A,D as e,d as r,s as t,S as s}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"L1 板载交换 + L2 通信柜、七子平面","description":"","frontmatter":{"title":"L1 板载交换 + L2 通信柜、七子平面","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ub-l1-l2-planes.md","filePath":"llm/ub-l1-l2-planes.md","lastUpdated":1791413859000}'),n={name:"llm/ub-l1-l2-planes.md"};function p(d,a,D,h,C,u){const B=L("Mermaid");return l(),i("div",null,[a[2]||(a[2]=E('<h1 id="l1-板载交换-l2-通信柜、七子平面" tabindex="-1">L1 板载交换 + L2 通信柜、七子平面 <a class="header-anchor" href="#l1-板载交换-l2-通信柜、七子平面" aria-label="Permalink to &quot;L1 板载交换 + L2 通信柜、七子平面&quot;">​</a></h1><div class="epigraph"><p>每个计算节点七颗板载 L1 交换，一一对着超节点里七个独立的 L2 子平面；上行聚合与节点内 UB 容量对齐，L2 不做带宽超额认购。</p><footer>—— CloudMatrix384 论文对板载 L1、通信柜 L2 与七子平面的公开拓扑</footer></div><p><a href="/llm/cloudmatrix-384">CloudMatrix 384</a> 的 UB 网不是「所有卡插进一台巨大交换机」。公开结构是两级：计算节点上的 <strong>L1 板载 UB 交换芯片</strong>，以及 4 个通信柜里的 <strong>L2 UB 交换</strong>。L2 被划分成 <strong>7 个独立子平面</strong>。每个节点的 7 颗 L1 与这 7 个子平面一一对应；每颗 L1 扇出 16 条链路，连到本子平面里的每一颗 L2 芯片。论文把该网络写成无阻塞：L2 层没有带宽超额认购，节点到 L2 的聚合上行与节点内部 UB 容量对齐。本篇只写这一层拓扑怎么读，端口速率用论文已给出的数字，不推断未给出的机柜内走线长度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>48 个计算节点、每节点 12 个处理器（8 NPU + 4 CPU）要全互连，若做成单级大交换，端口基数、供电和故障域都会集中到一个箱子。若做成节点两两直连，链路数按节点对数增长，布线先崩。两级星型（节点内汇聚到 L1，L1 再进 L2）用 \\(O(N)\\) 量级的上行逼近全互连的带宽目标，这是数据中心 Clos 也熟悉的思路；此处的差别是：交换芯片讲 <a href="/llm/ub-lingqu">UB</a>，L2 放在专用<strong>通信柜</strong>而不是每柜一个 ToR 以太网，而且切成七个平行平面而不是一张共享的脊。</p><p>切平面要回答：为什么是 7，而不是 1 或 48。公开配置里，每颗 910C 带七个高速收发器接入 UB；节点上放 7 颗 L1，与收发器/上行分组相匹配。一颗 L1 对应一个 L2 子平面，故障时可以损失一个平面的带宽，而不必把整张超节点网一分为二。把七个平面理解成「七个独立的以太网 VLAN」不准确——它们是 UB Scale-Up 的带宽切片。</p><p><span class="marginnote">直觉类比：七个子平面像七条平行的独立高速路，每座城市（节点）在每条路上都有一个出口。一条路堵了或封了，只是少七分之一的通行能力，别的路照跑；这比「一条巨型路」的隔离性好得多。为什么恰好七条？因为每颗 910C 物理上就有七组收发器。</span></p><h3 id="无阻塞在这句话里的意思" tabindex="-1">无阻塞在这句话里的意思 <a class="header-anchor" href="#无阻塞在这句话里的意思" aria-label="Permalink to &quot;无阻塞在这句话里的意思&quot;">​</a></h3><p>论文的无阻塞指：L2 交换层不过度订阅，节点内 UB 容量与「节点→L2」聚合上行匹配，因此跨节点流量在交换层不被人为收成更细的管道。它不是「任意 kernel 都能以该规格打满 384 卡」。近端 HBM、核启动、集合通信算法仍会限制有效带宽。无阻塞是拓扑承诺，不是应用屋顶线。</p><p><span class="marginnote">每个 L2 子平面含 16 颗 L2 UB 交换芯片；每颗 L2 芯片提供 48 个 28 GB/s 端口——这是论文写明的交换侧规格。单颗板载 L1 向上一层提供 448 GB/s 上行。不要把这些端口速率加总后当成「应用可见的 384 路全连接带宽」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读拓扑时按「节点 → 平面 → 通信柜」三步。</p><p>节点：8×910C + 4×鲲鹏经 UB 链接到 7 颗板载 L1，节点内是单层 UB 平面。处理器之间的盒内协同走 L1，不必出柜。出节点：每颗 L1 只进入自己的 L2 子平面，扇出 16 条，连到该平面 16 颗 L2 的每一颗。48 个计算节点都如此挂上同一组七平面，于是任意两节点之间可以经「源 L1 → 某 L2 → 目的 L1」相遇，而不经过第三计算节点转发。</p><p>通信柜：4 柜容纳全部 L2。计算柜与通信柜的相对位置决定跨柜必须走光还是还能走电，见 <a href="/llm/ub-optical-cabinets">跨柜光模块</a>。编排上，MatrixLink 一类组件管链路与 QoS；业务作业仍应假设「七平面是一份 UB 域」，不要让调度器按平面把 TP 组拆碎——除非产品文档明确支持按平面分域，384 论文把超节点写成一个逻辑节点。</p>',14)),(l(),A(s,null,{default:e(()=>[t(B,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TB%0A%20%20subgraph%20NODE%5B%22%E4%B8%80%E4%B8%AA%E8%AE%A1%E7%AE%97%E8%8A%82%E7%82%B9%22%5D%0A%20%20%20%20P%5B%228%C3%97910C%20%2B%204%C3%97%E9%B2%B2%E9%B9%8F%22%5D%0A%20%20%20%20L1A%5B%22L1%20%E8%8A%AF%E7%89%87%20%C3%977%22%5D%0A%20%20%20%20P%20---%20L1A%0A%20%20end%0A%20%20subgraph%20PLANES%5B%227%20%E4%B8%AA%E7%8B%AC%E7%AB%8B%20L2%20%E5%AD%90%E5%B9%B3%E9%9D%A2%22%5D%0A%20%20%20%20S1%5B%22%E5%AD%90%E5%B9%B3%E9%9D%A2%201%EF%BC%9A16%C3%97L2%22%5D%0A%20%20%20%20S2%5B%22%E5%AD%90%E5%B9%B3%E9%9D%A2%202%EF%BC%9A16%C3%97L2%22%5D%0A%20%20%20%20S7%5B%22%E2%80%A6%20%E5%AD%90%E5%B9%B3%E9%9D%A2%207%22%5D%0A%20%20end%0A%20%20L1A%20--%3E%7C%22L1%231%20%E6%89%87%E5%87%BA%2016%22%7C%20S1%0A%20%20L1A%20--%3E%7C%22L1%232%20%E6%89%87%E5%87%BA%2016%22%7C%20S2%0A%20%20L1A%20--%3E%7C%22L1%237%20%E6%89%87%E5%87%BA%2016%22%7C%20S7%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<h3 id="七平面与单卡-ub-带宽如何对上" tabindex="-1">七平面与单卡 UB 带宽如何对上 <a class="header-anchor" href="#七平面与单卡-ub-带宽如何对上" aria-label="Permalink to &quot;七平面与单卡 UB 带宽如何对上&quot;">​</a></h3><p>论文给每颗 910C 最高约 392 GB/s 单向 UB。七个平面并行，是把这张卡的 UB 带宽切到七组上行，而不是让一张卡只吃一个 28 GB/s 端口。规划集合通信时，应把「平面数」当成路径多样性：拥塞或单平面故障时，APR 一类机制（<a href="/llm/ub-mesh">UB-Mesh</a>）可以在仍存活的平面上借路。应用不必自己做七路打散，但要把 HCCL 绑定在整个超节点域，而不是绑定「我只用平面 3」。</p><p><span class="marginnote">数字实例：\\(392\\ \\text{GB/s} \\div 7\\) 个平面 \\(\\approx 56\\ \\text{GB/s}\\) 每平面每卡。单条 L2 端口 28 GB/s，所以每平面每卡约等于两条端口的上行。这就是「切平面不是把带宽切小，而是把带宽分组」的具体算术。</span></p><p>CPU 的 UB 约 160 GB/s 单向每插槽，同样经这 7 颗 L1 进平面。CPU–NPU 与 NPU–NPU 共享平面资源，池化 DRAM 的流量会与 TP All-Reduce 争用。把 KV 池打满再叠满载 EP，是同一套 L1/L2 上的调度问题，不是两张物理网。</p><p><span class="marginnote">只有 NPU 参加 RDMA 平面；L1/L2 描述的是 UB Scale-Up。不要把 3.2 Tbps 节点 RDMA 加进 L2 端口表。三平面分开记账。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>两级交换把「盒内全连」与「跨节点全连」拆开：盒内最短，跨节点固定多一到两跳交换，再加跨柜介质。七平面把单点交换故障的爆炸半径从「整网」降到「七分之一带宽」，代价是控制面要维护七张平行的链路状态。无过订阅意味着通信柜的端口与线必须按峰值配齐——这正是专用通信柜存在的原因：把 L2 的供电、光模块密度和散热从计算柜里拿出来，计算柜专注 8+4。</p><p>与对称 Clos 相比，这里的「脊」是 UB L2 而不是以太网脊；叶子是板载 L1 而不是 ToR。因此柜内计算托盘之间的 TP 不应再绕一圈数据中心叶子。编程若把 HCCL 默认套到 VPC 网卡，等于绕开七子平面。</p><h3 id="故障-平面、柜、节点" tabindex="-1">故障：平面、柜、节点 <a class="header-anchor" href="#故障-平面、柜、节点" aria-label="Permalink to &quot;故障：平面、柜、节点&quot;">​</a></h3><p>一颗 L1 坏：该节点在对应平面的上行丢失，节点总 UB 下降，其他平面仍在。一个 L2 子平面坏：全域该切片带宽丢失，七分之六仍在。一个通信柜坏：影响落在该柜承载的 L2 芯片集合，可能跨多个平面，爆炸半径大于单平面。一个计算节点坏：48 减 1，域还在。运维手册应按这四层写，而不是只写「NPU 掉了一张」。</p>',10)),(l(),A(s,null,{default:e(()=>[t(B,{id:"mermaid-71",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%93%AA%E9%87%8C%E5%9D%8F%E4%BA%86%3F%22%5D%20--%3E%20A%5B%22%E4%B8%80%E9%A2%97%20L1%20%E5%9D%8F%22%5D%0A%20%20F%20--%3E%20B%5B%22%E4%B8%80%E4%B8%AA%20L2%20%E5%AD%90%E5%B9%B3%E9%9D%A2%E5%9D%8F%22%5D%0A%20%20F%20--%3E%20C%5B%22%E4%B8%80%E4%B8%AA%E9%80%9A%E4%BF%A1%E6%9F%9C%E5%9D%8F%22%5D%0A%20%20F%20--%3E%20D%5B%22%E4%B8%80%E4%B8%AA%E8%AE%A1%E7%AE%97%E8%8A%82%E7%82%B9%E5%9D%8F%22%5D%0A%20%20A%20--%3E%20A1%5B%22%E8%AF%A5%E8%8A%82%E7%82%B9%E4%B8%A2%201%2F7%20%E4%B8%8A%E8%A1%8C%20%C2%B7%20%E5%85%B6%E4%BD%99%E5%B9%B3%E9%9D%A2%E4%BB%8D%E5%9C%A8%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E5%85%A8%E5%9F%9F%E4%B8%A2%E8%AF%A5%E5%88%87%E7%89%87%20%C2%B7%20%E5%89%A9%206%2F7%20%E5%B8%A6%E5%AE%BD%22%5D%0A%20%20C%20--%3E%20C1%5B%22%E5%BD%B1%E5%93%8D%E8%AF%A5%E6%9F%9C%E5%85%A8%E9%83%A8%20L2%20%C2%B7%20%E5%8D%8A%E5%BE%84%E5%8F%AF%E8%83%BD%E8%B7%A8%E5%A4%9A%E5%B9%B3%E9%9D%A2%22%5D%0A%20%20D%20--%3E%20D1%5B%22384%20%E5%8D%A1%E5%8F%98%20376%20%C2%B7%20%E8%B6%85%E8%8A%82%E7%82%B9%E5%9F%9F%E4%BB%8D%E5%9C%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把七子平面画成七个独立的超节点来调度小作业，除非编排层明确支持平面级切片。不要用以太网的 oversubscription 经验去「节省」L2 端口——论文的无阻塞假设会被打破，宽 EP 先受害。不要发明第七平面与第七颗收发器之外的「隐藏第八平面」。端口 28 GB/s、L1 上行 448 GB/s、NPU 392 GB/s 只引用论文，换代以后以新文档为准。</p><p>相对 <a href="/llm/ub-mesh">UB-Mesh</a> 论文里的柜内 2D 全直连，384 用 L1/L2 两级交换实现超节点规模，是可布线约束下的实现，不是对递归全互连原则的否定。</p><p><span class="marginnote">出处：arXiv:2506.12708 中计算节点、图 5 一类 L1–L2 拓扑、七子平面与无阻塞表述。通信柜数量为 4，计算柜 12。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>L1 在计算节点板载，7 颗交换对应 7 个 L2 子平面；L2 在 4 个通信柜。</li><li>每颗 L1 扇出 16 条到本平面全部 L2 芯片；拓扑按论文为无阻塞、L2 不过度订阅。</li><li>七平面是 UB 带宽切片与故障隔离，不是七个以太网 VLAN，也不是七个调度域（除非产品另说）。</li><li>CPU 与 NPU 的 UB 流量共享这些平面；RDMA 另账。</li><li>故障分层：L1、子平面、通信柜、计算节点。</li><li>出处：CloudMatrix384 公开论文的交换拓扑章节。</li></ul>',6))])}const P=o(n,[["render",p]]);export{c as __pageData,P as default};
